return class extends DCLogic {
  constructor(p) { super(p); this.state = { k: 0, full: false }; }
  renderVals() {
    const C = [{"h": "The lesson", "s": "The club requires a lesson with a club instructor first.", "f": "The flying club that owns the Piper requires its members to fly with a club instructor before using the new autopilot. This flight is one of those lessons."}, {"h": "Back from maintenance", "s": "It is the first flight since maintenance and an annual inspection.", "f": "The 1980 Piper had its annual inspection on 6 January 2023 and a new autopilot installed. The report lists 1 hour on the aircraft since that inspection."}, {"h": "Two instructors", "s": "Both men up front hold flight instructor certificates.", "f": "The 53 year old in the left seat also holds an airline transport certificate. The 68 year old in the right seat is the club instructor for this lesson."}, {"h": "The plan", "s": "Out from Wiley Post Airport in Oklahoma City, and back again.", "f": "No flight plan is filed. The Piper is to leave Wiley Post Airport in Oklahoma City and return there in daylight."}]; const k = this.state.k, c = C[k], full = this.state.full;
    const dots = C.map((x, j) => ({ st: 'width: ' + (j === k ? 18 : 6) + 'px; height: 6px; border-radius: 6px; background: ' + (j === k ? '#FF4F00' : '#EAEAE7') }));
    return { h: c.h, body: full ? c.f : c.s, n: (k + 1) + ' / ' + C.length, dots, mode: full ? 'Short' : 'More detail',
      toggle: () => this.setState({ full: !full }), prev: () => this.setState({ k: Math.max(0, k - 1) }), next: () => this.setState({ k: Math.min(C.length - 1, k + 1) }),
      first: k === 0, last: k === C.length - 1 };
  }
}

